"""
OSS / licence scan of the vendored ETSformer tree (decision D-12). Re-runnable; everything in the report is computed here.

    python oss_scan.py --vendored src --pristine <unpacked salesforce/ETSformer at the pinned commit> \
        --upstream Autoformer=<dir> --upstream Informer2020=<dir> --out OSS_SCAN.md

What it does
  1. sha256 of every vendored file and a byte-for-byte comparison with the pristine tree (proves the vendored copy is unmodified).
  2. Licence / copyright markers found inside the vendored files.
  3. Code-overlap check against the repositories ETSformer says it builds on: each vendored file is turned into a token
     stream (comments/whitespace ignored), cut into overlapping 10-token shingles, and the CONTAINMENT
     (share of the vendored file's shingles that also occur in an upstream file) is reported for the best-matching upstream file.
  4. Licence of each upstream repository (first lines of its LICENSE file) and of the runtime dependencies (package metadata).
Files with containment >= REVIEW_AT are flagged for human review; the scan does not decide what is acceptable.
"""
import argparse, hashlib, io, tokenize, importlib.metadata as md
from pathlib import Path

N, REVIEW_AT = 10, 0.15


def sha(p: Path) -> str:
    return hashlib.sha256(p.read_bytes()).hexdigest()


def shingles(p: Path) -> set:
    toks = []
    try:
        for t in tokenize.generate_tokens(io.StringIO(p.read_text(errors="ignore")).readline):
            if t.type in (tokenize.NAME, tokenize.OP, tokenize.NUMBER, tokenize.STRING):
                toks.append(t.string)
    except (tokenize.TokenError, IndentationError, SyntaxError):
        pass
    return {tuple(toks[i:i + N]) for i in range(max(0, len(toks) - N + 1))}


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--vendored", required=True); ap.add_argument("--pristine", required=True)
    ap.add_argument("--upstream", action="append", default=[]); ap.add_argument("--out", required=True)
    ap.add_argument("--license", default=None, help="the ETSformer LICENSE.txt (default: searched upward from --pristine)")
    a = ap.parse_args()
    vend, prist = Path(a.vendored), Path(a.pristine)
    files = sorted(f for f in vend.rglob("*.py"))
    L = ["# OSS / licence scan -- vendored ETSformer\n", "Generated by `oss_scan.py`; every figure below is computed, none is asserted.\n"]
    L.append("## 1. Integrity: vendored files vs the pristine upstream tree\n\n| file | sha256 | identical to pristine |\n|---|---|---|")
    for f in files:
        rel = f.relative_to(vend); pf = prist / rel
        L.append(f"| `{rel}` | `{sha(f)[:16]}...` | {'yes' if pf.exists() and sha(pf) == sha(f) else 'NO'} |")
    L.append("\n## 2. Licence / copyright markers inside the vendored files\n")
    for f in files:
        hits = [ln.strip() for ln in f.read_text(errors="ignore").splitlines() if any(k in ln.lower() for k in ("copyright", "licen", "spdx", "adapted from", "based on", "borrowed"))]
        L.append(f"- `{f.relative_to(vend)}`: {'; '.join(hits[:3]) if hits else 'no licence/copyright/attribution marker in the file'}")
    up = {}
    for spec in a.upstream:
        name, path = spec.split("=", 1)
        up[name] = Path(path)
    L.append(f"\n## 3. Code overlap with the repositories ETSformer says it builds on ({N}-token shingles, containment)\n")
    L.append("| vendored file | " + " | ".join(f"best match in {n}" for n in up) + " |\n|---|" + "---|" * len(up))
    upfiles = {n: [(p, shingles(p)) for p in sorted(d.rglob("*.py"))] for n, d in up.items()}
    flagged = []
    for f in files:
        sv = shingles(f)
        cells = []
        for n, lst in upfiles.items():
            best = (0.0, None)
            for p, su in lst:
                c = len(sv & su) / len(sv) if sv else 0.0
                if c > best[0]:
                    best = (c, p)
            cells.append(f"{best[0]:.3f} (`{best[1].relative_to(up[n])}`)" if best[1] else "0.000")
            if best[0] >= REVIEW_AT:
                flagged.append((f.relative_to(vend), n, best[0], best[1].relative_to(up[n])))
        L.append(f"| `{f.relative_to(vend)}` | " + " | ".join(cells) + " |")
    L.append(f"\nFlagged for human review (containment >= {REVIEW_AT}): " + ("none" if not flagged else ""))
    for r in flagged:
        L.append(f"- `{r[0]}` overlaps `{r[1]}/{r[3]}` at {r[2]:.3f}")
    L.append("\n## 4. Licences\n\nUpstream repositories (first lines of their LICENSE file):\n")
    for n, d in up.items():
        lic = next((d / x for x in ("LICENSE", "LICENSE.txt", "LICENSE.md") if (d / x).exists()), None)
        L.append(f"- **{n}**: " + (" / ".join(l.strip() for l in lic.read_text(errors='ignore').splitlines()[:3] if l.strip()) if lic else "NO LICENSE FILE FOUND"))
    lic_file = Path(a.license) if a.license else next((q / "LICENSE.txt" for q in [prist, *prist.parents] if (q / "LICENSE.txt").exists()), None)
    L.append("- **salesforce/ETSformer**: " + (" / ".join(l.strip() for l in lic_file.read_text().splitlines()[:2] if l.strip()) + " (BSD-3-Clause text; notice retained in `LICENSE.txt`)" if lic_file else "NO LICENSE FILE FOUND"))
    L.append("\nRuntime dependencies the vendored code imports (from installed package metadata):\n")
    for pkg in ("torch", "einops", "scipy", "numpy"):
        try:
            m = md.metadata(pkg)
            lic = m.get("License-Expression") or (m.get("License") or "").splitlines()[0][:80] or "; ".join(c.split("::")[-1].strip() for c in m.get_all("Classifier", []) if c.startswith("License"))
            L.append(f"- {pkg} {m['Version']}: {lic or 'not stated in metadata'}")
        except md.PackageNotFoundError:
            L.append(f"- {pkg}: not installed")
    Path(a.out).write_text("\n".join(L) + "\n")
    print("\n".join(L))


if __name__ == "__main__":
    main()
